    "text": "বাংলাদেশে তড়িৎ-এর কম্পাঙ্ক (frequency) প্রতি সেকেন্ডে ৫০ সাইকেল-এর তাৎপর্য কি?",
    "optionA": "প্রতি সেকেন্ডে বিদ্যুৎ প্রবাহ ৫০ বার বদ্ধ হয়",
