    "id": "q_bulk_1788675152835_1",
    "text": "The speaker failed to make the audience ______ to him patiently. – Which of the following is the correct verb form in the blank above",
    "optionA": "to listen",
    "optionB": "listening",
    "optionC": "listened",
    "optionD": "listen",
    "correct": "Option D",
    "explanation": "সঠিক উত্তর 'listen'। কারণ 'make' causative verb-এর পর verb-এর base form (infinitive without 'to') বসে। Structure: make + object + base verb. যেমন: He made me laugh. 'to listen' (full infinitive) 'make'-এর পর বসে না। 'listening' (gerund) ও 'listened' (past participle) ভুল। তাই 'listen' সঠিক।",
