    "id": "q_bulk_1788675152835_12",
    "text": "‘ঠক চাচা’ চরিত্রটি কোন উপন্যাসে পাওয়া যায়?",
    "optionA": "আলালের ঘরের দুলাল",
    "optionB": "জোহরা",
    "optionC": "মৃত্যুক্ষুধা",
    "optionD": "হাজার বছর ধরে",
    "correct": "Option A",
    "explanation": "ঠক চাচা' চরিত্রটি প্যারীচাঁদ মিত্র (১৮১৪-১৮৮৩) রচিত 'আলালের ঘরের দুলাল' (১৮৫৮) উপন্যাসে পাওয়া যায়। এটি বাংলা সাহিত্যের প্রথম সামাজিক উপন্যাস। 'ঠক চাচা' চরিত্রটি ধূর্ত ও প্রবঞ্চক হিসেবে চিত্রিত। 'জোহরা' (১৮৫৫) মীর মশাররফ হোসেনের রচনা; 'মৃত্যুক্ষুধা' (১৯৩০) কাজী নজরুল ইসলামের উপন্যাস; 'হাজার বছর ধরে' (১৯৬৪) জহির রায়হানের উপন্যাস।",
