    "id": "q_bulk_1788675152835_15",
    "text": "‘Boot leg’ means to-",
    "optionA": "distribute",
    "optionB": "export",
    "optionC": "import",
    "optionD": "smuggle",
    "correct": "Option D",
    "explanation": "Boot leg' অর্থ 'চোরাচালান করা' (smuggle)। এটি বিশেষ করে অবৈধভাবে মদ বা অন্যান্য পণ্য পরিবহন বোঝাতে ব্যবহৃত হয়। 'Distribute' অর্থ বিতরণ করা, 'Export' অর্থ রপ্তানি করা, 'Import' অর্থ আমদানি করা। 'Bootleg' শব্দটি মূলত মার্কিন যুক্তরাষ্ট্রে নিষিদ্ধ মদের সময় (Prohibition era) থেকে ব্যবহৃত হয়।",
