    "id": "q_bulk_1788675152835_21",
    "text": "শুদ্ধ বানানটি নির্দেশ করুন-",
    "optionA": "মুহুর্মুহু",
    "optionB": "মূহুর্মুহু",
    "optionC": "মুর্হুমূর্হু",
    "optionD": "মুর্হুর্মূহু",
    "correct": "Option A",
    "explanation": "মুহুর্মুহু' শুদ্ধ বানান। অর্থ: বারংবার, পুনঃপুন। বানানের নিয়ম: 'মুহুঃ' শব্দের সাথে 'মুহুঃ' যোগে 'মুহুর্মুহু' হয় (বিসর্গের স্থানে 'র'-এর আগম ঘটে)। 'মূহুর্মুহু' বানান ভুল কারণ 'মুহুঃ' এখানে দীর্ঘ 'ঊ' হবে না। 'মুর্হু' শুদ্ধ নয় কারণ এটি ভুল উচ্চারণ। বাংলা একাডেমি প্রণীত বানানরীতি অনুসারে 'মুহুর্মুহু' শুদ্ধ।",
