    "text": "নদীর একপাশ থেকে গুণ টেনে নৌকাকে মাঝ নদীতে রেখেই সামনের দিকে নেয়া সম্ভব হয় কিভাবে?",
    "optionA": "যথাযথভাবে হাল ঘুরিয়ে",
    "optionB": "নদী স্রোতের সুকৌশল ব্যবহারে",
    "optionC": "গুণ টানার সময় টানটি সামনের দিকে রেখে",
    "optionD": "পাল ব্যবহার করে",
    "correct": "Option A",
    "explanation": "নদীর একপাশ থেকে গুণ টেনে নৌকাকে মাঝ নদীতে রেখে সামনের দিকে নেয়ার জন্য যথাযথভাবে হাল ঘুরিয়ে নিতে হয়। গুণ টানা হলে নৌকার দিক পরিবর্তন হয়, হালের সাহায্যে তা নিয়ন্ত্রণ করে সামনের দিকে এগোতে পারে। নদী স্রোত বা পাল ব্যবহার গৌণ।",
