    "id": "q_bulk_1788675152835_24",
    "text": "বিশ্বব্যাংক -এর কোন অঙ্গ সংগঠনটি ‘Soft Ioan Window’ নামে পরিচিত?",
    "optionA": "IBRD",
    "optionB": "IDA",
    "optionC": "IFC",
    "optionD": "EDI",
    "correct": "Option B",
    "explanation": "বিশ্বব্যাংকের 'IDA' (International Development Association)-কে 'Soft Loan Window' বা নরম ঋণ সুবিধা বলা হয়। এটি স্বল্প-উন্নত দেশগুলিকে কম সুদে দীর্ঘমেয়াদী ঋণ দেয়। IBRD (International Bank for Reconstruction and Development) হলো মূল বিশ্বব্যাংক (হার্ড লোন উইন্ডো), IFC (International Finance Corporation) বেসরকারি খাতে বিনিয়োগ করে, EDI (Economic Development Institute) প্রশিক্ষণ প্রদান করে।",
