    "id": "q_bulk_1788675152835_33",
    "text": "‘The World Economic Forum’ কর্তৃক নির্ধারিত International Competitiveness Ranking- এ ২০১৯ সালে কোন দেশ সর্বোচ্চ স্থান অধিকার করেছে?",
