    "explanation": "ইচ্ছা' বিশেষ্যের বিশেষণ 'ইচ্ছুক'। অর্থ: যে ইচ্ছা রাখে বা ইচ্ছা আছে এমন। 'ইচ্ছাময়' অর্থ ইচ্ছায় পূর্ণ, কিন্তু এটি বিশেষণ হলেও তেমন চলিত নয়। 'ঐচ্ছিক' অর্থ ইচ্ছা অনুসারে বা স্বেচ্ছায়, কিন্তু এটি 'ইচ্ছা' থেকে ভিন্ন অর্থে ব্যবহৃত হয়। 'অনিচ্ছা' অর্থ ইচ্ছার অভাব, যা বিশেষ্য। সঠিক বিশেষণ 'ইচ্ছুক'।",
