    "text": "বাতাসের নাইট্রোজেন কিভাবে মাটির উর্বরতা বৃদ্ধি করে?",
    "optionA": "সরাসরি মাটিতে মিশ্রিত হয়ে জৈব বস্তু প্রস্তুত করে",
    "optionB": "ব্যাকটেরিয়ার সাহায্যে উদ্ভিদের গ্রহণ উপযোগী বস্তু প্রস্তুত করে",
    "optionC": "পানিতে মিশে মাটিতে শোষিত হওয়ার ফলে",
    "optionD": "মাটির অজৈব লবণকে পরিবর্তিত করে",
    "correct": "Option C",
    "explanation": "বাতাসের নাইট্রোজেন ব্যাকটেরিয়া (যেমন: Rhizobium, Azotobacter)-এর সাহায্যে নাইট্রেট ও নাইট্রাইটে রূপান্তরিত হয়, যা উদ্ভিদ গ্রহণ করতে পারে (নাইট্রোজেন ফিক্সেশন)। 'সরাসরি মাটিতে মিশে' বা 'পানিতে মিশে' সঠিক নয়, কারণ নাইট্রোজেন অক্রিয় গ্যাস। এনজাইম নাইট্রোজেনেজ এই প্রক্রিয়ায় সাহায্য করে।",
