    "text": "বিশ্বের কোন শহর ‘নিষিদ্ধ শহর’ নামে পরিচিত?",
    "optionA": "লাসা",
    "optionB": "উলানবটোর",
    "optionC": "পিয়ংইয়ং",
    "optionD": "কাবুল",
    "correct": "Option A",
    "explanation": "নিষিদ্ধ শহর' (Forbidden City) নামে পরিচিত লাসা (তিব্বত, চীন)। এটি তিব্বতের প্রাচীন রাজপ্রাসাদ ও ধর্মীয় কেন্দ্র ছিল, বহুদিন বিদেশীদের জন্য নিষিদ্ধ ছিল। উলানবটোর (মঙ্গোলিয়া), পিয়ংইয়ং (উত্তর কোরিয়া), কাবুল (আফগানিস্তান) এ নামে পরিচিত নয়। তবে 'Forbidden City' সাধারণত বেইজিংয়ের প্রাসাদকে বলা হয়, কিন্তু এখানে লাসা সঠিক।",
