    "optionB": "সাড়ে ৫ ঘণ্টা",
    "optionC": "সাড়ে ৬ ঘণ্টা",
    "optionD": "৫ ঘণ্টা",
    "correct": "Option A",
    "explanation": "গ্রিনিচ মান সময় (GMT) অপেক্ষা বাংলাদেশ সময় ৬ ঘণ্টা আগে (অর্থাৎ GMT+৬)। সাড়ে ৫ ঘণ্টা (GMT+৫:৩০) ভারতের সময়, সাড়ে ৬ ঘণ্টা মিয়ানমারের, ৫ ঘণ্টা পাকিস্তানের।",
