    "text": "What is the synonym of ‘incredible’?",
    "optionA": "Unbelievable",
    "optionB": "Unthinkable",
    "optionC": "Unlikely",
    "optionD": "Unthinking",
    "correct": "Option A",
    "explanation": "Incredible' শব্দের সমার্থক 'Unbelievable' (অবিশ্বাস্য)। 'Unthinkable' অর্থ অচিন্তনীয়, 'Unlikely' অর্থ অসম্ভাব্য, 'Unthinking' অর্থ অচিন্তাশীল। 'Incredible' ল্যাটিন 'incredibilis' থেকে এসেছে যার অর্থ যা বিশ্বাস করা যায় না।",
