    "text": "ট্রাজেডি, কমেডি ও ফার্সের মূল পার্থক্য-",
    "optionA": "জীবনানুভূতির গভীরতায়",
    "optionB": "দূষ্টিভঙ্গির সূক্ষ্মতায়",
    "optionC": "কাহিনীর সরলতা ও জটিলতায়",
    "optionD": "ভাষার প্রকারভেদে",
    "correct": "Option A",
    "explanation": "ট্রাজেডি (বিয়োগান্ত নাটক), কমেডি (হাস্যরসাত্মক নাটক) ও ফার্স (প্রহসন)-এর মূল পার্থক্য জীবনানুভূতির গভীরতায়। ট্রাজেডি জীবন ও ভাগ্যের গভীর সংকট তুলে ধরে, কমেডি সামাজিক অসঙ্গতি ও হাস্যরসের মাধ্যমে জীবনকে উপস্থাপন করে, ফার্স হালকা ও অমূলক হাস্যরসে ভরপুর। দৃষ্টিভঙ্গি, কাহিনী ও ভাষাগত পার্থক্য গৌণ।",
