    "id": "q_bulk_1788675152835_64",
    "text": "আফ্রিকা মহাদেশের মানচিত্রে Horns of Africa -তে কোন দেশটি অবস্থিত?",
    "optionA": "ইথিওপিয়া",
    "optionB": "নাইজেরিয়া",
    "optionC": "কেনিয়া",
    "optionD": "সুদান",
    "correct": "Option A",
    "explanation": "Horn of Africa' (আফ্রিকার শৃঙ্গ) হলো আফ্রিকার পূর্ব প্রান্তে অবস্থিত একটি উপদ্বীপ, যেখানে ইথিওপিয়া, সোমালিয়া, ইরিত্রিয়া ও জিবুতি অবস্থিত। নাইজেরিয়া পশ্চিম আফ্রিকায়, কেনিয়া পূর্ব আফ্রিকায় (শৃঙ্গের দক্ষিণে), সুদান উত্তর-পূর্ব আফ্রিকায়। সঠিক উত্তর ইথিওপিয়া।",
