    "text": "x + y – 1 = 0, x – y + 1 = 0 এবং y + 3 = 0 সরল রেখা তিনটি দ্বারা গঠিত ত্রিভুজটি-",
    "optionA": "সমবাহু",
    "optionB": "বিষমবাহু",
    "optionC": "সমকোণী",
    "optionD": "সমদ্বিবাহু",
    "correct": "Option C",
    "explanation": "রেখাগুলো: 1) x+y=1, 2) x-y=-1, 3) y=-3। রেখা 1 ও 2 পরস্পর লম্ব (ঢাল m₁=-1, m₂=1, গুণফল -1)। তাই ত্রিভুজটি সমকোণী। সমবাহু, বিষমবাহু বা সমদ্বিবাহু কিনা তা বিন্দু নির্ণয় করে যাচাই করতে হয়। কিন্তু যেহেতু দুটি রেখা লম্ব, তাই ত্রিভুজ সমকোণী।",
