    "optionD": "কোনো চাঁদা দিতে হয় না",
    "correct": "Option C",
    "explanation": "ইসলামিক উন্নয়ন ব্যাংকে (IDB) বাংলাদেশের চাঁদার হার ১০.০ মিলিয়ন ইসলামিক দিনার (সদস্য রাষ্ট্রের মূলধনের ভিত্তিতে)। এটি IDB-এর প্রতিষ্ঠাকালীন (১৯৭৫) সদস্যপদের সময় নির্ধারিত হয়েছিল। ২৫.০ মিলিয়ন, ১৫.৫ মিলিয়ন ভুল। বাংলাদেশ সক্রিয় সদস্য বলে 'কোনো চাঁদা দিতে হয় না' ভুল।",
