    "id": "q_bulk_1788675152835_72",
    "text": "The word ‘plurality’ means-",
    "optionA": "The letter ‘S’",
    "optionB": "Men and women",
    "optionC": "Chaos and confusion",
    "optionD": "The holding of more than one office at a time",
    "correct": "Option D",
    "explanation": "Plurality' শব্দের অর্থ হলো 'একাধিক পদ বা কার্যালয় একই সময়ে ধারণ করা'। রাজনীতি ও আইনে এটি ব্যবহৃত হয়। যেমন: He holds a plurality of offices. 'The letter S' হলো plural form-এর প্রতীক কিন্তু 'plurality' নয়। 'Men and women' অর্থ 'plurality' নয়, 'Chaos and confusion' অর্থ বিশৃঙ্খলা। সঠিক অর্থ 'plurality' = বহুত্ব বা একাধিক পদাধিকার।",
