    "id": "q_bulk_1788675152835_79",
    "text": "My uncle has three sons, ____ work in the same office. Which of the following is the best form of pronoun in the above sentence?",
    "optionA": "All of them",
    "optionB": "Who all",
    "optionC": "they all",
    "optionD": "All of whom",
    "correct": "Option D",
    "explanation": "সঠিক উত্তর 'All of whom'। কারণ এটি একটি non-defining relative clause-এর শুরুতে ব্যবহৃত হয়। এখানে 'three sons' হলো antecedent, এবং 'all of whom' তা নির্দেশ করছে। 'All of them' একটি সম্পূর্ণ বাক্য হতে পারে কিন্তু এখানে comma-এর পর clause শুরু করতে পারে না। 'Who all' ভুল কারণ 'all' সাধারণত 'who'-এর পরে বসে না। 'They all' একটি প্রধান বাক্য শুরু করতে পারে কিন্তু এখানে relative clause প্রয়োজন। সঠিক structure: My uncle has three sons, all of whom work in the same office.",
