    "id": "q_bulk_1788675152835_81",
    "text": "বাংলাদেশের GDP-তে কৃষিখাতের অবদান কত শতাংশ?",
    "optionA": "১৫.৩৩",
    "optionB": "৭৫",
    "optionC": "৩২",
    "optionD": "১৩.৪৭",
    "correct": "Option D",
    "explanation": "বাংলাদেশের জিডিপিতে কৃষিখাতের অবদান (২০২২-২৩ অর্থবছর) প্রায় ১৩.৪৭%। যা পূর্ববর্তী বছরের তুলনায় কিছুটা কমেছে। ১৫.৩৩% পুরোনো তথ্য (২০১৯-২০)। ৭৫% ও ৩২% কৃষি খাতের কর্মসংস্থানে অবদান (প্রায় ৪০% কর্মসংস্থান) নির্দেশ করে, কিন্তু জিডিপিতে নয়। সঠিক উত্তর ১৩.৪৭%।",
