    "explanation": "Georgian Age (১৯১০-১৯৩৬) হলো সবচেয়ে সাম্প্রতিক। Augustan Age (১৭০০-১৭৪৫), Victorian Age (১৮৩৭-১৯০১), Restoration Age (১৬৬০-১৭০০) - এগুলো Georgrian Age-এর পূর্ববর্তী। Georgian Age-এর নামকরণ করা হয়েছে King George V-এর নামে। এই যুগে Thomas Hardy, H.G. Wells, Rudyard Kipling প্রমুখ সাহিত্যিক ছিলেন।",
