    "optionD": "ফুসফুসে হঠাৎ বিকল হয়ে যাওয়া",
    "correct": "Option B",
    "explanation": "স্ট্রোক' হলো মস্তিষ্কে রক্তক্ষরণ বা রক্তপ্রবাহে বাধার কারণে মস্তিষ্কের কোষের ক্ষতি। এটি হঠাৎ অজ্ঞান বা মৃত্যুর কারণ হতে পারে। হৃদপিণ্ডের সংকোচন হলো হার্ট অ্যাটাক, হৃদপিণ্ডের অসাড়তা হার্ট ফেইলিওর, ফুসফুসের বিকলতা রেসপিরেটরি ফেইলিওর।",
