    "explanation": "সঠিক preposition 'at'। কারণ 'at the weekend' ব্রিটিশ ইংরেজিতে সঠিক (আমেরিকান ইংরেজিতে 'on the weekend' ব্যবহৃত হয়)। 'in' সাধারণত মাস/বছরের জন্য, 'on' নির্দিষ্ট তারিখ/দিনের জন্য, 'for' সময়কালের জন্য ব্যবহৃত হয়। প্রশ্নটি ব্রিটিশ ইংরেজি অনুসারে 'at the weekend' সঠিক।",
