    "text": "পৃথিবীর বিভিন্ন দেশের মধ্যে জনসংখ্যার দিক থেকে বাংলাদেশের স্থান কততম?",
    "optionA": "অষ্টম",
    "optionB": "নবম",
    "optionC": "দ্বাদশ",
    "optionD": "চতুর্দশ",
