    "explanation": "১৯০৫ সালের বঙ্গভঙ্গের পর নবগঠিত পূর্ববঙ্গ ও আসাম প্রদেশের প্রথম লেফটেন্যান্ট গভর্নর ছিলেন স্যার ব্যামফিল্ড ফুলার (১৯০৫-১৯০৬)। লর্ড কার্জন ছিলেন ভারতের ভাইসরয় (১৮৯৯-১৯০৫) যিনি বঙ্গভঙ্গ করেছিলেন। লর্ড মিন্টো (১৯০৫-১৯১০) ছিলেন পরবর্তী ভাইসরয়। ওয়ারেন হেস্টিংস ছিলেন প্রথম গভর্নর জেনারেল (১৭৭৪-১৭৮৫)।",
